// scripts/bundle-utils.js
//
// 全国バンドル系の共通ユーティリティ:
//  - HTTP ダウンロード（タイムアウト・User-Agent）
//  - ZIP 解凍（unzip コマンドへの委譲）
//  - 簡易 GML パース（点・線・面の抽出）
//  - 共通出力フォーマット（JSON or varint+base64）
//  - グリッド索引生成
//
// 使われ方:
//   const u = require('./bundle-utils.js');
//   const buf = await u.fetchBuffer(url);
//   const features = u.gmlExtractPoints(text, attrTagPattern);
//   u.writeBundleFile('coarse-jp.js', 'COARSE_JP', { ... });

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const {
  PRECISION,
  GRID_INT,
  gridKey,
  encodeIndexListB64,
  encodeLineB64,
  encodePolygonsBytes,
} = require('./encoding-utils.js');

const UA = { 'User-Agent': 'Daikou-app-test/0.1 (zeroact24.729@outlook.com)' };

// ─── HTTP ─────────────────────────────────────────────────────
async function fetchBuffer(url, timeoutMs = 240000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: ctrl.signal, headers: UA });
    if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText} for ${url}`);
    return Buffer.from(await res.arrayBuffer());
  } finally {
    clearTimeout(t);
  }
}

async function fetchText(url, timeoutMs = 60000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { signal: ctrl.signal, headers: UA });
    if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
    return await res.text();
  } finally {
    clearTimeout(t);
  }
}

// ─── ZIP ──────────────────────────────────────────────────────
function unzip(zipPath, outDir) {
  fs.mkdirSync(outDir, { recursive: true });
  execSync(`unzip -o "${zipPath}" -d "${outDir}"`, { stdio: 'pipe' });
}

function findFiles(dir, extPattern) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...findFiles(p, extPattern));
    else if (extPattern.test(e.name)) out.push(p);
  }
  return out;
}

// ─── 簡易 GML パース ──────────────────────────────────────────
// すべて posList を抽出し、座標列を取り出すミニパーサ。
// KSJ の各データセットでは feature ごとに <gml:posList>...</gml:posList> 内に
// 緯度経度がスペース区切りで列挙される。属性は周辺の <ksj:XXX>...</ksj:XXX> 等。

function parseLatLngList(posListText) {
  const nums = posListText
    .trim()
    .split(/\s+/)
    .map(Number)
    .filter((n) => !isNaN(n));
  const out = [];
  for (let i = 0; i + 1 < nums.length; i += 2) {
    out.push([nums[i], nums[i + 1]]); // [lat, lng]
  }
  return out;
}

// 単純な posList 抽出（point/line/polygon 区別なく座標列だけ取る）
function gmlExtractAllPosLists(gmlText) {
  const re = /<gml:posList[^>]*>([\s\S]*?)<\/gml:posList>/g;
  const out = [];
  let m;
  while ((m = re.exec(gmlText)) !== null) out.push(parseLatLngList(m[1]));
  return out;
}

// ksj:* 属性タグを「フィーチャ単位の塊ごと」に拾う
// 各フィーチャは <ksj:Feature ... > ... </ksj:Feature> で囲まれているか、
// あるいは要素のグループで分かれていることが多い。
// シンプル戦略：feature 名で split → 各塊から ksj 属性 + posList を取る
function gmlSplitByFeatureTag(gmlText, featureTagName) {
  // featureTagName: 例 'ksj:RailroadStation', 'ksj:DesignatedShelter' 等
  const open = `<${featureTagName}`;
  const close = `</${featureTagName}>`;
  const blocks = [];
  let i = 0;
  while (true) {
    const s = gmlText.indexOf(open, i);
    if (s === -1) break;
    const e = gmlText.indexOf(close, s);
    if (e === -1) break;
    blocks.push(gmlText.slice(s, e + close.length));
    i = e + close.length;
  }
  return blocks;
}

// 要素ブロックから ksj:* 属性を全部拾う（タグ名 → 値）
function gmlExtractKsjAttrs(blockText) {
  const out = {};
  const re = /<ksj:([A-Za-z0-9_]+)[^>]*>([\s\S]*?)<\/ksj:\1>/g;
  let m;
  while ((m = re.exec(blockText)) !== null) {
    const k = m[1];
    const v = m[2].trim();
    if (v && !v.startsWith('<')) out[k] = v;
  }
  return out;
}

// ─── 出力ファイル書き込み ────────────────────────────────────
function writeBundleJs(outFile, varName, dataObj, headerLines = []) {
  const dir = path.dirname(outFile);
  fs.mkdirSync(dir, { recursive: true });
  const header = [
    `// Auto-generated by scripts/bundle-utils.js`,
    `// Generated: ${new Date().toISOString()}`,
    ...headerLines,
    `window.${varName} = ${JSON.stringify(dataObj)};`,
    '',
  ].join('\n');
  fs.writeFileSync(outFile, header);
  return fs.statSync(outFile).size;
}

// ─── Point cloud → grid + JSON ────────────────────────────────
// items: [{ lat, lng, ...other }, ...]   座標は度単位
// attrFn: (item) => ({...trimmed attrs to keep})
// 出力: { v, generated, precision, bbox, gridSize, items, grid }
function buildPointBundle(items, attrFn, version = 1) {
  const bbox = [Infinity, Infinity, -Infinity, -Infinity];
  const out = [];
  const grid = {};
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    if (typeof it.lat !== 'number' || typeof it.lng !== 'number') continue;
    const latI = Math.round(it.lat * PRECISION);
    const lngI = Math.round(it.lng * PRECISION);
    if (latI < bbox[0]) bbox[0] = latI;
    if (lngI < bbox[1]) bbox[1] = lngI;
    if (latI > bbox[2]) bbox[2] = latI;
    if (lngI > bbox[3]) bbox[3] = lngI;
    const point = { lat: latI, lng: lngI };
    Object.assign(point, attrFn(it) || {});
    out.push(point);
    const key = gridKey(latI, lngI);
    (grid[key] ||= []).push(out.length - 1);
  }
  return {
    v: version,
    generated: new Date().toISOString(),
    precision: PRECISION,
    bbox: out.length ? bbox : null,
    gridSize: GRID_INT,
    items: out,
    grid,
  };
}

// KSJ ZIP は通常 UTF-8/ ディレクトリに *.geojson を同梱している
// （Shift-JIS/ にも同じデータがあるが文字化けの恐れがあるため UTF-8 を優先）
function findKsjGeoJSON(dir) {
  const utf8Dir = path.join(dir, 'UTF-8');
  if (fs.existsSync(utf8Dir)) {
    return findFiles(utf8Dir, /\.geojson$/i);
  }
  // フォールバック: 直下を探す
  return findFiles(dir, /\.geojson$/i);
}

// 任意ジオメトリから代表点 [lat, lng] を取得（buildPointBundle 等で使う）
function representativeLatLng(geometry) {
  if (!geometry) return null;
  if (geometry.type === 'Point') {
    const c = geometry.coordinates;
    return { lat: c[1], lng: c[0] };
  }
  // 全座標の平均（簡易重心）
  let sumLat = 0,
    sumLng = 0,
    n = 0;
  function walk(node) {
    if (!Array.isArray(node)) return;
    if (typeof node[0] === 'number' && typeof node[1] === 'number') {
      sumLng += node[0];
      sumLat += node[1];
      n++;
      return;
    }
    for (const v of node) walk(v);
  }
  walk(geometry.coordinates);
  if (n === 0) return null;
  return { lat: sumLat / n, lng: sumLng / n };
}

// KSJ ZIP を DL → 解凍 → UTF-8/*.geojson の features を返す
//   opts.layerFilter: (filename) => boolean   true を返したファイルだけ読む
async function loadKsjFeaturesFromZipUrl(zipUrl, tmpDir, opts = {}) {
  fs.mkdirSync(tmpDir, { recursive: true });
  const zipName = path.basename(zipUrl);
  const zipPath = path.join(tmpDir, zipName);
  const cacheValid =
    fs.existsSync(zipPath) &&
    Date.now() - fs.statSync(zipPath).mtimeMs < (opts.cacheMs || 7 * 86400000);
  if (!cacheValid) {
    const buf = await fetchBuffer(zipUrl);
    fs.writeFileSync(zipPath, buf);
  }
  unzip(zipPath, tmpDir);
  const geojsonFiles = findKsjGeoJSON(tmpDir);
  const features = [];
  const fileCounts = {};
  for (const gp of geojsonFiles) {
    const base = path.basename(gp);
    if (opts.layerFilter && !opts.layerFilter(base)) {
      fileCounts[base] = '(skipped)';
      continue;
    }
    const text = fs.readFileSync(gp, 'utf8');
    const fc = JSON.parse(text);
    if (Array.isArray(fc.features)) {
      for (const f of fc.features) features.push(f);
      fileCounts[base] = fc.features.length;
    }
  }
  return { features, fileCounts, zipPath, zipBytes: fs.statSync(zipPath).size };
}

module.exports = {
  fetchBuffer,
  fetchText,
  unzip,
  findFiles,
  findKsjGeoJSON,
  parseLatLngList,
  gmlExtractAllPosLists,
  gmlSplitByFeatureTag,
  gmlExtractKsjAttrs,
  representativeLatLng,
  loadKsjFeaturesFromZipUrl,
  writeBundleJs,
  buildPointBundle,
  PRECISION,
  GRID_INT,
  gridKey,
  encodeIndexListB64,
  encodeLineB64,
  encodePolygonsBytes,
};
